#include <string>
#include <stack>

using namespace std;

class Solution {
public:
    bool isValidSerialization(string preorder) {
        int slots = 1;
        int n = preorder.size();

        for (int i = 0; i < n; i++) {
            if (preorder[i] == ',') continue;
            if (--slots < 0) return false;
            if (preorder[i] != '#') slots += 2;
            while (i < n && preorder[i] != ',') i++;
        }

        return slots == 0;
    }
};
